// minItems: 1
companies?: Array<
string // minLength: 1
>,
// Only contacts created at or after this time (ISO 8601, e.g. 2026-10-01T00:00:00Z).
createdAfter?: string, // pattern: /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/, format: "date-time"
// Only contacts created at or before this time (ISO 8601).
createdBefore?: string, // pattern: /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$/, format: "date-time"
// Only contacts created by any of these teammates (Quo user IDs, US…, from list-users).
// minItems: 1
createdBy?: Array<
string // pattern: /^US[A-Za-z0-9]+$/
>,
// Only contacts with any of these exact email addresses. Each is also tried in lowercase, since addresses are usually stored that way.
// minItems: 1
emails?: Array<
string // pattern: /^(?:[A-Za-z0-9_'+\-]+\.)*[A-Za-z0-9_'+\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\-]*\.)+[A-Za-z]{2,}$/, format: "email"
>,
