// The user's Quo number to call from. Accepts E.164 (e.g. '+15551234567'), a phone-number ID, or a recognizable local format. The user must be a member of it — use list-inboxes to discover available numbers.
from: string,
// The number the AI agent calls, in E.164 format (e.g. '+15551234567').
to: string,
// A specific instruction stating the intended outcome, relevant context and constraints the AI agent needs to act on. Resolve missing or ambiguous details with the user before calling; do not invent them. For scheduling, include acceptable dates, times and timezone (e.g. 'Book a 30-minute consultation next Friday between 2pm and 4pm America/Toronto; if unavailable, collect alternatives without booking').
task: string, // minLength: 1, maxLength: 2000
// What to do if voicemail answers. Defaults to hang-up.
voicemail?: "hang-up" | "leave-message",
// What the AI agent says after the beep. Implies voicemail: 'leave-message'; a short call-back request when omitted.
voicemailMessage?: string, // minLength: 1, maxLength: 1000
// The longest the call may last once answered, in seconds. Defaults to 300.
maxDurationSeconds?: integer, // minimum: 1, maximum: 600
// Set true only after the user explicitly confirmed this call (from number, number to call and task) in the conversation. Never infer it.
